mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
const { onInbound, check } = await import(process.argv[2]);

const H = 3600e3;
const t0 = new Date('2026-10-23T10:00:00Z');
const at = (h) => new Date(t0.getTime() + h * H);
let n = 0;
const ok = (fn, msg) => { fn(); n++; console.log('ok', msg); };

// never written: freeform blocked, template allowed
ok(() => assert.deepEqual(check('new', 'freeform', at(0)), { allowed: false, rule: 'freeform-outside-24h-window' }), 'never-written freeform blocked');
ok(() => assert.deepEqual(check('new', 'template', at(0)), { allowed: true, rule: null }), 'never-written template allowed');

// 24h window
onInbound('a', 'hi', at(0));
ok(() => assert.deepEqual(check('a', 'freeform', at(23.9)), { allowed: true, rule: null }), 'freeform inside 24h');
ok(() => assert.equal(check('a', 'freeform', at(24)).allowed, false), 'freeform at exactly 24h blocked');
ok(() => assert.equal(check('a', 'template', at(100)).allowed, true), 'template after window allowed');
onInbound('a', 'again', at(30));
ok(() => assert.equal(check('a', 'freeform', at(40)).allowed, true), 'window reopens on new inbound');

// keyword normalization
const variants = ['STOP', 'stop', ' Stop ', 'stop!', 'STOP.', '"stop"', 'Stop!!!', 'stop ', 'ｓｔｏｐ', 'st​op', 'stop 🛑', 'Unsubscribe', 'STOPALL', 'cancel', 'QUIT', 'end'];
for (const v of variants) {
  onInbound('b', v, at(1));
  ok(() => assert.deepEqual(check('b', 'template', at(2)), { allowed: false, rule: 'opted-out' }), `opt-out via ${JSON.stringify(v)}`);
  onInbound('b', 'START', at(3));
  ok(() => assert.equal(check('b', 'template', at(4)).allowed, true), `restored after START (after ${JSON.stringify(v)})`);
}
// opt-in words
for (const v of ['start', ' Start. ', 'UNSTOP', 'unstop!']) {
  onInbound('c', 'stop', at(0));
  onInbound('c', v, at(1));
  ok(() => assert.equal(check('c', 'freeform', at(2)).allowed, true), `opt-in via ${JSON.stringify(v)}`);
}

// ordinary sentences are not keywords
for (const v of ['my bus stop is far', 'please stop texting me', 'stop it', 'I want to start over', 'do not end this', 'cancel my order please', 'stopping by later', 'stops', 'the end of the month']) {
  onInbound('d', v, at(0));
  ok(() => assert.equal(check('d', 'template', at(1)).allowed, true), `not a keyword: ${JSON.stringify(v)}`);
}

// stop from never-written customer still blocks later template
onInbound('e', 'STOP', at(0));
ok(() => assert.equal(check('e', 'template', at(1)).allowed, false), 'opt-out before any other contact');

// out-of-order inbound timestamp does not shorten window
onInbound('f', 'hi', at(10));
onInbound('f', 'hi again', at(5));
ok(() => assert.equal(check('f', 'freeform', at(30)).allowed, true), 'older inbound does not move window back');

// input validation
ok(() => assert.throws(() => check('a', 'sms', at(0)), TypeError), 'bad type throws');
ok(() => assert.throws(() => check('a', 'freeform', '2026-10-23'), TypeError), 'bad now throws');
ok(() => assert.throws(() => onInbound('a', 'x', new Date('nope')), TypeError), 'invalid at throws');

console.log(`\n${n} checks passed`);
EOF
